export function habilidadeMatchesAno(habilidade, ano) {
  return !ano || habilidade.ano.split(';').map((item) => item.trim()).includes(ano);
}

export function searchBnccHabilidades({
  ano = "",
  componente = "",
  area = "",
  termo = "",
  culturaMaker = false
} = {}) {
  const normalizedTerm = termo.trim().toLowerCase();

  return bnccHabilidades.filter((habilidade) => {
    const matchesAno = habilidadeMatchesAno(habilidade, ano);
    const matchesComponente = !componente || habilidade.componente === componente;
    const matchesArea = !area || habilidade.area === area;
    const matchesMaker = !culturaMaker || habilidade.cultura_maker;
    const searchable = [
      habilidade.codigo,
      habilidade.descricao,
      habilidade.unidade_tematica,
      habilidade.objeto_conhecimento,
      ...habilidade.palavras_chave,
      ...habilidade.temas_relacionados,
      ...habilidade.steam_relacionado
    ].join(" ").toLowerCase();
    const matchesTerm = !normalizedTerm || searchable.includes(normalizedTerm);

    return matchesAno && matchesComponente && matchesArea && matchesMaker && matchesTerm;
  });
}
